<?php
require __DIR__.'/config.php';
$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT p.*,c.nome categoria FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id WHERE p.id=? AND p.ativo=1");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Produto não encontrado. <a href="index.php">Voltar</a>');}
$variants=db()->prepare("SELECT * FROM variantes_estoque WHERE produto_id=? AND estoque>0 ORDER BY tamanho,cor");$variants->execute([$id]);$vs=$variants->fetchAll();$price=$p['preco_promocional']!==null?(float)$p['preco_promocional']:(float)$p['preco'];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$vid=(int)($_POST['variante_id']??0);$qty=max(1,min(10,(int)($_POST['quantidade']??1)));$vst=db()->prepare("SELECT * FROM variantes_estoque WHERE id=? AND produto_id=? AND estoque>=?");$vst->execute([$vid,$id,$qty]);$v=$vst->fetch();if($v){$_SESSION['cart'][$vid]=min($v['estoque'],($_SESSION['cart'][$vid]??0)+$qty);header('Location: carrinho.php?adicionado=1');exit;}else{$error='Selecione uma variação disponível.';}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($p['nome'])?> | Loja BY</title><link rel="stylesheet" href="style.css"></head><body><header class="top"><a class="brand" href="index.php"><span class="logo">BY</span><span>LOJA BY<small>SUA MARCA, SEU ESTILO</small></span></a><nav class="nav"><a href="index.php">Voltar à loja</a><a href="carrinho.php">Carrinho (<?=cart_count()?>)</a></nav></header><main class="wrap"><div class="card" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:28px"><img src="<?=h($p['imagem_url'])?>" alt="<?=h($p['nome'])?>" style="width:100%;max-height:600px;object-fit:cover;border-radius:12px"><div><span class="tag"><?=h($p['categoria']??'Loja BY')?></span><h1><?=h($p['nome'])?></h1><div class="price" style="font-size:27px"><?=money($price)?></div><p><?=nl2br(h($p['descricao']))?></p><?php if(isset($error)):?><div class="notice error"><?=h($error)?></div><?php endif?><form method="post"><?php if($vs):?><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="field"><label>Tamanho / cor</label><select name="variante_id" required><option value="">Escolha uma opção</option><?php foreach($vs as $v):?><option value="<?=$v['id']?>"><?=h($v['tamanho'])?> — <?=h($v['cor'])?> (<?=$v['estoque']?> em estoque)</option><?php endforeach?></select></div><div class="field" style="margin:15px 0"><label>Quantidade</label><input type="number" name="quantidade" min="1" max="10" value="1"></div><button class="btn">Adicionar ao carrinho</button></form><?php else:?><div class="notice">Estoque/variações ainda não cadastrados. Entre em contato com a loja.</div><?php endif?><p class="muted">Fotos ilustrativas. Confirme tamanho e disponibilidade antes de finalizar.</p></div></div></main><footer class="footer">LOJA BY — Sua marca, seu estilo.</footer></body></html>
